solution.solution.js:
class TaskError extends Error {
  constructor(message) {
    super(message);
    this.name = "TaskError";
  }
}

class Task {
  #id;
  #title;
  constructor(id, title, { priority = 3, tags = [] } = {}) {
    this.#id = id;
    this.#title = title;
    this.priority = priority;
    this.tags = [...tags];
    this.done = false;
  }
  get id() { return this.#id; }
  get title() { return this.#title; }
  complete() {
    if (this.done) throw new TaskError("already done");
    this.done = true;
  }
  toString() {
    const tags = this.tags.map(t => ` #${t}`).join("");
    return `[${this.done ? "x" : " "}] ${this.#title} (p${this.priority})${tags}`;
  }
}

class Board {
  #tasks = new Map();
  #nextId = 1;

  add(title, options = {}) {
    const clean = String(title ?? "").trim();
    if (!clean) throw new TaskError("title is empty");
    const priority = options.priority ?? 3;
    if (!Number.isInteger(priority) || priority < 1 || priority > 5) throw new TaskError("priority must be 1 to 5");
    const task = new Task(this.#nextId++, clean, { ...options, priority });
    this.#tasks.set(task.id, task);
    return task;
  }

  get(id) {
    const task = this.#tasks.get(id);
    if (!task) throw new TaskError(`no task ${id}`);
    return task;
  }

  complete(id) { this.get(id).complete(); }

  remove(id) {
    this.get(id);
    this.#tasks.delete(id);
  }

  *tasks({ done, tag } = {}) {
    const sorted = [...this.#tasks.values()].sort((a, b) => a.priority - b.priority || a.id - b.id);
    for (const t of sorted) {
      if (done !== undefined && t.done !== done) continue;
      if (tag !== undefined && !t.tags.includes(tag)) continue;
      yield t;
    }
  }

  summary() {
    const all = [...this.tasks()];
    if (all.length === 0) return "no tasks";
    const doneCount = all.filter(t => t.done).length;
    const next = all.find(t => !t.done);
    const tail = next ? `next: ${next.title} (priority ${next.priority})` : "nothing left";
    return `${doneCount} of ${all.length} done; ${tail}`;
  }

  toJSON() {
    return [...this.#tasks.values()].map(t => ({ id: t.id, title: t.title, priority: t.priority, tags: [...t.tags], done: t.done }));
  }

  static fromJSON(text) {
    const board = new Board();
    for (const { id, title, priority, tags, done } of JSON.parse(text)) {
      const task = new Task(id, title, { priority, tags });
      task.done = done;
      board.#tasks.set(id, task);
      board.#nextId = Math.max(board.#nextId, id + 1);
    }
    return board;
  }
}

unitTests:
test("the example", () => {
  const board = new Board();
  const a = board.add("Write report", { priority: 2, tags: ["work"] });
  const b = board.add("Buy milk");
  checkEq([a.id, b.id], [1, 2]);
  board.complete(b.id);
  checkEq([...board.tasks({ done: false })].map(t => t.title), ["Write report"]);
  checkEq(board.summary(), "1 of 2 done; next: Write report (priority 2)");
});

test("task details", () => {
  const board = new Board();
  const tags = ["work", "home"];
  const t = board.add("  Plan trip  ", { priority: 1, tags });
  tags.push("oops");
  checkEq(t.title, "Plan trip");
  checkEq(t.tags, ["work", "home"]);
  checkEq(String(t), "[ ] Plan trip (p1) #work #home");
  t.complete();
  checkEq(String(t), "[x] Plan trip (p1) #work #home");
  checkEq(String(board.add("Nap")), "[ ] Nap (p3)");
  t.title = "changed?";
  checkEq(t.title, "Plan trip");
});

test("misuse throws TaskError", () => {
  const board = new Board();
  checkThrows(() => board.add("   "), TaskError);
  checkThrows(() => board.add("x", { priority: 0 }), TaskError);
  checkThrows(() => board.add("x", { priority: 2.5 }), TaskError);
  checkThrows(() => board.get(9), TaskError);
  const t = board.add("x");
  board.complete(t.id);
  try { board.complete(t.id); check(false, "should throw"); }
  catch (e) { checkEq([e.name, e.message], ["TaskError", "already done"]); }
  try { board.remove(42); check(false, "should throw"); }
  catch (e) { checkEq(e.message, "no task 42"); }
  check(new TaskError("m") instanceof Error, "TaskError should extend Error");
});

test("filtering and sorting", () => {
  const board = new Board();
  board.add("c", { priority: 3, tags: ["home"] });
  board.add("a", { priority: 1 });
  board.add("d", { priority: 3, tags: ["home", "work"] });
  board.add("b", { priority: 2, tags: ["work"] });
  board.complete(4);
  checkEq([...board.tasks()].map(t => t.title), ["a", "b", "c", "d"]);
  checkEq([...board.tasks({ tag: "work" })].map(t => t.title), ["b", "d"]);
  checkEq([...board.tasks({ tag: "work", done: false })].map(t => t.title), ["d"]);
  checkEq([...board.tasks({ done: true })].map(t => t.id), [4]);
  const gen = board.tasks();
  checkEq(typeof gen.next, "function");
});

test("summaries", () => {
  const board = new Board();
  checkEq(board.summary(), "no tasks");
  const t = board.add("only");
  board.complete(t.id);
  checkEq(board.summary(), "1 of 1 done; nothing left");
  board.remove(t.id);
  checkEq(board.summary(), "no tasks");
});

test("save and load", () => {
  const board = new Board();
  board.add("one", { tags: ["x"] });
  board.add("two", { priority: 1 });
  board.add("three");
  board.complete(2);
  board.remove(3);
  const text = JSON.stringify(board);
  checkEq(JSON.parse(text), [
    { id: 1, title: "one", priority: 3, tags: ["x"], done: false },
    { id: 2, title: "two", priority: 1, tags: [], done: true },
  ]);
  const back = Board.fromJSON(text);
  checkEq(back.summary(), "1 of 2 done; next: one (priority 3)");
  checkEq(back.add("four").id, 3);
  check(back.get(2) instanceof Task, "restored tasks should be Task objects");
});

